p = 'new_II-a.tex'
s = open(p, encoding='utf-8').read()


def rep(a, b):
    global s
    assert s.count(a) == 1, (s.count(a), a[:70])
    s = s.replace(a, b)


rep(r"""Let $F\to F'$ be a monomorphism of functors $\Delta'\to\mathrm{Ab}$ and $\xi\in F([n])$ an element whose image in $\varinjlim F'$ is zero. Then there are finitely many maps $h_j:[n]\to[N]$ and integers $c_j$ with $\sum_jc_j=1$ and $\sum_jc_jF'(h_j)\xi=0$ in $F'([N])$ (the colimit is the quotient of $\bigoplus F'([m])$ by the elements $F'(v)\eta-\eta$; push a relation expressing $\xi$ forward to a common $[N]$). Choose $t$ for $N$. Since $t\circ h_j=:\tau$ does not depend on $j$, applying $F'(t)=\sum t_gF'(g)$ gives $F'(\tau)\xi=\sum_jc_jF'(t)F'(h_j)\xi=0$, where $\tau$ has coefficient sum $1$. As $F\subseteq F'$, also $F(\tau)\xi=0$, and the class of $\xi$ in $\varinjlim F$, which equals that of $F(\tau)\xi$, is zero. So $\varinjlim_{\Delta'}$ preserves monomorphisms and is exact; $\Delta'$ is nonempty and connected, and the proposition applies.\hfill$\square$""",
    r"""Let $F\subseteq F'$ be functors $\Delta'\to\mathrm{Ab}$. Any two objects of $\Delta'$ map to a third, so every element of $\varinjlim F$ is the class of one element $\xi\in F([n])$. Suppose its image in $\varinjlim F'$ is zero. The colimit is the quotient of $\bigoplus_mF'([m])$ by the elements $F'(v)\eta-\eta$, so $\xi=\sum_k(F'(v_k)\eta_k-\eta_k)$ in this direct sum, for finitely many $v_k:[s_k]\to[r_k]$ and $\eta_k\in F'([s_k])$. Choose $N$ and maps $d_m:[m]\to[N]$ for the finitely many $m$ that occur; applying $F'(d_m)$ on each summand gives $F'(d_n)\xi=\sum_k\bigl(F'(d_{r_k}v_k)-F'(d_{s_k})\bigr)\eta_k$ in $F'([N])$. Choose $t$ for $N$ and write $F'(t)=\sum_gt_gF'(g)$. Since $t\circ d_{r_k}v_k=t\circ d_{s_k}$, applying $F'(t)$ gives $F'(\tau)\xi=0$ for $\tau=t\circ d_n$, a combination of maps $[n]\to[M]$ with coefficient sum $1$. As $F\subseteq F'$, also $F(\tau)\xi=0$. The class of $F(g)\xi$ in $\varinjlim F$ is the class of $\xi$ for every $g$, so the class of $F(\tau)\xi$ is that of $\xi$; it is zero. So $\varinjlim_{\Delta'}$ preserves monomorphisms and is exact; $\Delta'$ is nonempty and connected, and the proposition applies.\hfill$\square$""")

rep(r"""The functors $P_c$ are projective with $\varinjlim P_c=\mathbf Z$, and $\varinjlim d=0$. Hence $L_1\varinjlim\mathbf Z[H]=\varinjlim J=\operatorname{coker}(\varinjlim K\to\mathbf Z)$.""",
    r"""The functors $P_c$ are projective with $\varinjlim P_c=\mathbf Z$, and $\varinjlim d=0$. So $L_1\varinjlim\mathbf Z[H]$ is the kernel of $\varinjlim J\to\varinjlim P_p$; this map is zero, because $\varinjlim P_{q'}\to\varinjlim J$ is surjective and $\varinjlim d=0$. Hence $L_1\varinjlim\mathbf Z[H]=\varinjlim J=\operatorname{coker}(\varinjlim K\to\mathbf Z)$, the image of $\varinjlim K$ being generated by the coefficient sums of the elements of the groups $K(r)$.""")

rep(r"""So $1$ is a sum of coefficient sums of elements of the groups $K(r_i)$; pushing these finitely many elements to a common successor $r$ of the $r_i$ (the proposition above) and adding gives $t$.""",
    r"""So $1$ is a sum of coefficient sums of finitely many elements of groups $K(r_i)$; pushing them to a common successor $r$ of the $r_i$ (the common-successor proposition of the preceding commentary) and adding gives $t$.""")

rep(r"""\textit{Let $A$ have an object $q$ that receives an arrow from every object; for instance a monoid, or a category with finitely many objects and common successors. Then $T(A)$ holds if and only if $A$ is filtered.}""",
    r"""\textit{Let $A$ have an object $q$ that receives an arrow from every object. Then $T(A)$ holds if and only if $A$ is filtered. This applies to every monoid, and to every category with finitely many objects, where both $T(A)$ and filteredness provide such an object $q$.}""")
open(p, 'w', encoding='utf-8', newline='\n').write(s)
print('ok')
